use baal_transport_service::{Config,DisabledCredentials,Permit,ReadOnlyAuthority,Receipt,RequestSpec,Scope,SystemClock,Transport};
use moloch_live_runtime::{dispatch::DispatchLog,feedback,fundamental_policy::*};
use moloch_replay::session::{ExclusiveLock,Session};
use serde_json::{Value,json};
use sha2::{Digest,Sha256};
use std::{collections::BTreeSet,path::PathBuf,sync::Arc};
pub const NOW:u64=1_792_108_800_000;
pub const T:&str="11111111-1111-1111-1111-111111111111";
pub fn iso(t:u64)->String{moloch_live_runtime::daily_windows::iso(t).unwrap()}
pub fn sha(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
pub fn digest(v:&Value)->String{sha(&serde_json::to_vec(v).unwrap())}
pub struct Temp(pub PathBuf);impl Drop for Temp{fn drop(&mut self){let _=std::fs::remove_dir_all(&self.0);}}
pub struct F{pub bank:Session,pub log:DispatchLog,pub store:Option<Cohorts>,pub transport:Transport,pub owner:Arc<ExclusiveLock>,pub scope:Scope,pub review:ReviewInput,pub originals:Vec<Vec<u8>>,pub trust:BTreeSet<String>,pub policy:Value,pub seed:Value,pub book_version:u64,pub root:Temp}
impl F{
 pub fn new(passive:Option<u64>,p:&str,bps:u32,fee:&str,managed:bool)->Self{Self::new_at(passive,p,bps,fee,managed,NOW)}
 pub fn new_at(passive:Option<u64>,p:&str,bps:u32,fee:&str,managed:bool,at:u64)->Self{
  let root=Temp(std::env::temp_dir().join(format!("passive-inherited-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos())));std::fs::create_dir(&root.0).unwrap();let owner=Arc::new(ExclusiveLock::acquire(&root.0.join("owner.lock")).unwrap());
  let policy=json!({"initialCash":"1000.000000","maximumCommitted":"1000.000000","maximumMarketCost":"100.000000","maximumMarkets":3,"quantity":3,"entryStopAt":iso(at+3600000),"inventoryExitMode":"fixedGain","maximumInventoryAgeMs":60000,"inventoryMinimumGain":"0.005000","inventoryAgeClock":"execution","feeBps":bps,"feePerShare":fee});let seed=json!({"runId":"passive-inherited-fixture","availableCash":"1000.000000","accountSnapshotHash":"a".repeat(64),"observedAt":iso(at-10000)});
  let bank=Session::open_live(&root.0.join("bank"),&policy,&seed).unwrap();let log=DispatchLog::open(&root.0.join("dispatch.ndjson")).unwrap();let scope=Scope{tournament_id:T.into(),tournament_slug:"cup".into(),exchanges:[("101".into(),"201".into())].into()};
  let node=json!({"market_id":"201","root":{"node_type":"contract","node_id":"301","contract_id":"301","contract_type":"Election Outcome","contract_details":{"contractType":"Election Outcome","resolutionType":"Party Winner","winnerName":"Republican Party","electionDate":"2026-11-03","officeLevel":"Federal","usState":"Synthetic","raceId":1,"stageId":2,"raceName":"Synthetic fixture","raceStage":"General"},"settled_with":null,"settlement_date":null,"title":"Synthetic Republican Party Winner fixture"}});
  let originals=vec![b"synthetic forecast; no live probability claim".to_vec(),b"synthetic official ballot".to_vec(),serde_json::to_vec(&node).unwrap()];let sources=["forecast","official_ballot","official_contract_node"].iter().enumerate().map(|(i,k)|json!({"kind":k,"url":format!("https://fixture.invalid/{k}"),"sha256":sha(&originals[i]),"publishedAtMs":at-100,"observedAtMs":at-50,"maximumAgeMs":180000})).collect::<Vec<_>>();
  let review:ReviewInput=serde_json::from_value(json!({"version":1,"reviewerId":"test-operator","assumptionLabel":"Synthetic inherited-only probability and party mapping assumptions; no calibration or fill promise","runId":"passive-inherited-fixture","bankManifestSha256":bank.manifest_hash(),"tournamentId":T,"marketId":"201","exchangeId":"101","contractId":"301","side":"NO","officialContractRootSha256":official_contract_root_sha256(&node).unwrap(),"ordinaryProbability":p,"exceptionalProbabilityAllowance":"0.010000","minimumExceptionalPayout":"0.000000","marginPerShare":"0.010000","maximumPrincipal":"4.000000","maximumQuantity":5,"reviewedAtMs":at,"expiresAtMs":at+180000,"holdUntilMs":at+600000,"payoutMappingIsOperatorAssumption":true,"revokeExisting":false,"sources":sources})).unwrap();
  let transport=Transport::new_for_mock(Config{queue_dir:root.0.join("original-account-queue"),account_scope:"synthetic-passive-inherited-account".into(),scope:scope.clone(),maximum_pages:2,writes_enabled:false},Box::new(DisabledCredentials),Box::new(SystemClock),Box::new(ReadOnlyAuthority),"http://127.0.0.1:9/api/v1".into()).unwrap();
  let mut f=Self{bank,log,store:None,transport,owner,scope,review,originals,trust:BTreeSet::new(),policy,seed,book_version:0,root};f.book(at-5000);f.retire(at-1);
  let adoption=json!({"type":"actual_position_adoption","source":"official_sig_api_v1","authority":"human_moloch_inherited_management_20261015","complete":true,"receiptHash":"d".repeat(64),"requestStartedAt":iso(at-1),"receivedAt":iso(at),"processedAt":iso(at),"tournamentId":T,"openingCost":"1.900000","effectiveMaximumMarkets":4,"positions":[{"exchangeId":"101","marketId":"201","quantity":-3,"lotPrincipal":"1.900000","reportedCostBasis":"1.900000","reportedMinusLotPrincipal":"0.000000","basisClassification":"exact","lots":[{"lotId":"501","quantity":1,"side":"NO","entryPrice":"0.900000","openedAt":iso(at-86400000)},{"lotId":"502","quantity":2,"side":"NO","entryPrice":"0.500000","openedAt":iso(at-43200000)}]}]});f.bank.accept("fixture-adoption",1,&adoption).unwrap();if managed{f.manage(at+1);}f.retire(at+3001);
  f.store=Some(Cohorts::initialize(&f.root.0,&f.bank,&f.log,f.owner.clone()).unwrap());let snapshot=ExistingSnapshot::capture(&f.bank,&f.log,&f.transport,"fixture-adoption",1,&adoption,"101").unwrap();f.review.existing_origin=Some(snapshot.approval().clone());f.review.passive_value_exit=passive.map(|maximum_quantity|PassiveValueExit{version:1,maximum_quantity});let reviewed=f.verify(f.review.clone(),at+3001);f.store.as_mut().unwrap().install_existing(reviewed,snapshot,&f.bank,&f.log,&f.transport,at+3001).unwrap();f.book(at+4000);f.retire(at+7001);f
 }
 pub fn verify(&mut self,r:ReviewInput,at:u64)->Reviewed{self.trust.insert(review_sha256(&r).unwrap());let hashes=self.originals.iter().map(|b|sha(b)).collect::<Vec<_>>();let bytes=self.originals.iter().enumerate().map(|(i,b)|SourceBytes{sha256:&hashes[i],bytes:b}).collect::<Vec<_>>();Reviewed::verify(r,&bytes,&self.trust,at).unwrap()}
 pub fn install(&mut self,r:ReviewInput,at:u64){let checked=self.verify(r.clone(),at);self.store.as_mut().unwrap().install(checked,&self.bank,&self.log,at).unwrap();self.review=r;}
 pub fn event(&mut self,mut e:Value){if e.get("processedAt").is_none(){e["processedAt"]=e["receivedAt"].clone();}let n=self.bank.last_source_sequence("fixture-original")+1;self.bank.accept("fixture-original",n,&e).unwrap();}
 pub fn book(&mut self,at:u64){self.book_version+=1;let seq=self.book_version;self.bank.accept("fixture-books",seq,&json!({"type":"book","receivedAt":iso(at),"processedAt":iso(at),"book":{"marketId":"201","exchangeId":"101","tournamentId":T,"sequence":seq.to_string(),"sourceAt":iso(at),"requestStartedAt":iso(at),"receivedAt":iso(at),"bids":[{"price":"0.300000","quantity":100}],"asks":[{"price":"0.320000","quantity":100}]}})).unwrap();}
 pub fn retire(&mut self,at:u64){for q in self.bank.engine().order_records(){let id=q["id"].as_u64().unwrap();if q["retired"]==false{assert!(self.log.never_attempted(id)&&!self.log.intents.contains_key(&id));let proof=self.log.proof(id);self.log.append(json!({"kind":"not_sent","qid":id,"proof":proof})).unwrap();self.event(json!({"type":"unsubmitted_intent_retired","source":"moloch_live_dispatcher","orderId":id,"confirmedNetworkAttempts":0,"receiptHash":digest(&proof),"receivedAt":iso(at),"deferPlanningForPackage":true}));}}}
 pub fn manage(&mut self,at:u64){let e=json!({"type":"managed_inventory_planning_v1","source":"moloch_live_dispatcher","receivedAt":iso(at),"processedAt":iso(at),"bankScope":{"runId":"passive-inherited-fixture","bankManifestHash":self.bank.manifest_hash(),"tournamentId":T},"bankHead":self.bank.durable_head(),"expectedReportSha256":digest(&self.bank.engine().report().unwrap()),"managedExchangeIds":["101"],"approvedReviewSetSha256":"b".repeat(64),"generationSha256":"0".repeat(64),"controlSha256":"c".repeat(64),"expectedPreviousModeSha256":null});self.event(e);}
 pub fn plan(&self,at:u64)->feedback::Result<Option<ExistingExit>>{self.store.as_ref().unwrap().prepare_existing_exit(&self.bank,&self.log,&self.transport,&self.scope,"101",&self.trust,at)}
 pub fn reserve(&mut self)->Value{self.reserve_at(NOW+7001)}
 pub fn reserve_at(&mut self,at:u64)->Value{let plan=self.plan(at).unwrap().unwrap();let seq=self.bank.last_source_sequence("reviewed-existing")+1;self.bank.accept("reviewed-existing",seq,plan.event()).unwrap();self.bank.engine().order_records().into_iter().find(|q|q["retired"]==false&&q["reviewedInventoryExit"]["executionMode"]=="passiveValueLimit").unwrap()}
 pub fn spec(&self,q:&Value)->RequestSpec{RequestSpec{method:"POST".into(),endpoint:"/orders".into(),body:Some(json!({"idempotencyKey":format!("passive-inherited-fixture:{}",q["id"].as_u64().unwrap()),"tournamentId":T,"exchangeId":"101","side":"no","action":"sell","quantity":q["quantity"],"price":serde_json::from_str::<Value>(q["price"].as_str().unwrap()).unwrap(),"expirationDate":iso(q["expiresAt"].as_u64().unwrap())})),body_json:None}}
 pub fn bind(&mut self,q:&Value,at:u64)->RequestSpec{let spec=self.spec(q);self.store.as_mut().unwrap().bind(&self.bank,&self.log,&self.scope,q["id"].as_u64().unwrap(),&spec,&self.trust,at).unwrap();spec}
 pub fn attempt(&mut self,q:&Value,spec:&RequestSpec,at:u64){let id=q["id"].as_u64().unwrap();self.log.append(json!({"kind":"intent","qid":id,"quote":q,"spec":spec,"fundamental":self.store.as_ref().unwrap().durable_tag(id).unwrap()})).unwrap();self.log.append(json!({"kind":"attempt","qid":id,"at":iso(at)})).unwrap();}
 pub fn ack(&mut self,q:&Value,at:u64){let r=receipt("/orders",json!({"orderId":"901","exchangeId":"101","side":"no","action":"sell","quantity":q["quantity"],"price":serde_json::from_str::<Value>(q["price"].as_str().unwrap()).unwrap()}),at,at);let e=feedback::acknowledgment(q,&r,&iso(at)).unwrap();self.store.as_ref().unwrap().validate_acknowledgment(q["id"].as_u64().unwrap(),&e).unwrap();self.log.append(json!({"kind":"ack","qid":q["id"],"receipt":r})).unwrap();self.event(e);}
 pub fn reopen(mut self)->Self{self.store.take();drop(self.bank);self.bank=Session::open_live(&self.root.0.join("bank"),&self.policy,&self.seed).unwrap();self.store=Some(Cohorts::open(&self.root.0,&self.bank,&self.log,self.owner.clone()).unwrap());self}
}
pub fn receipt(endpoint:&str,data:Value,start:u64,end:u64)->Receipt{Receipt{endpoint:endpoint.into(),request_started_at:iso(start),received_at:iso(end),status:200,data}}
pub fn tape(q:&Value,total:i64,at:u64)->Receipt{receipt("/orders/901/fills?limit=200",json!({"orderId":"901","exchangeId":"101","tournamentId":T,"coverage":{"complete":true},"pagination":{"hasMore":false,"nextCursor":null},"totalQuantityFilled":-total,"data":if total==0{json!([])}else{json!([{"id":"1001","quantity":-total,"side":"no","price":serde_json::from_str::<Value>(q["price"].as_str().unwrap()).unwrap(),"filledAt":iso(at-1)}])}}),at,at)}

